const emb = $json.embeddings;
const vector = Array.isArray(emb[0]) ? emb[0] : emb;

return [
  {
    json: {
      question: $('Set - Normalizar entrada').first().json.question,
      session_id: $('Set - Normalizar entrada').first().json.session_id,
      vector,
      vector_length: Array.isArray(vector) ? vector.length : -1,
      first_values: Array.isArray(vector) ? vector.slice(0, 5) : []
    }
  }
];

const qdrantBody = $json.body || {};
const results = Array.isArray(qdrantBody.result) ? qdrantBody.result : [];
const intent = $('Code - Detectar intención').first().json.intent || "general";
const question = ($('Set - Normalizar entrada').first().json.question || "").toLowerCase();

const requestedEtapas = [];
if (question.includes("bachillerato")) requestedEtapas.push("bachillerato");
if (
  question.includes("formación profesional") ||
  question.includes("formacion profesional") ||
  question.includes(" fp") ||
  question.includes("ciclos formativos")
) {
  requestedEtapas.push("fp");
}

const uniqueRequestedEtapas = [...new Set(requestedEtapas)];

const rawChunks = results.map((item, index) => {
  const payload = item.payload || {};

  return {
    original_index: index + 1,
    score: item.score ?? 0,
    source: payload.documento || payload.document || `doc_${index + 1}`,
    text: (payload.pageContent || "").trim(),
    tipo: (payload.tipo || "").toString().toLowerCase(),
    etapa: (payload.etapa || "").toString().toLowerCase(),
    curso: (payload.curso || "").toString().toLowerCase()
  };
}).filter(chunk => chunk.text.length > 0);

function isCompatibleWithIntent(chunk, intent) {
  const haystack = (chunk.source + " " + chunk.text).toLowerCase();

  if (intent === "matricula") {
    if (chunk.tipo && chunk.tipo !== "matricula") return false;
    if (/admisi[oó]n extraordinaria|vacantes|solicitud|petici[oó]n/i.test(haystack)) return false;
  }

  if (intent === "admision") {
    if (chunk.tipo && chunk.tipo !== "admision") return false;
  }

  if (intent === "oferta") {
    if (chunk.tipo && chunk.tipo !== "oferta") return false;
  }

  if (intent === "calendario") {
    if (chunk.tipo && chunk.tipo !== "calendario") return false;
  }

  return true;
}

function isCompatibleWithEtapa(chunk, requestedEtapas) {
  if (requestedEtapas.length === 0) return true;
  if (!chunk.etapa) return false;
  return requestedEtapas.includes(chunk.etapa);
}

function keywordBoost(chunk, intent) {
  const haystack = (chunk.source + " " + chunk.text).toLowerCase();
  let boost = 0;

  if (intent === "matricula") {
    if (/matr[ií]cul|formaliz/.test(haystack)) boost += 0.15;
    if (/admisi[oó]n|vacantes|solicitud/.test(haystack)) boost -= 0.12;
  } else if (intent === "admision") {
    if (/admisi[oó]n|solicitud/.test(haystack)) boost += 0.15;
    if (/matr[ií]cul|formaliz/.test(haystack)) boost -= 0.05;
  } else if (intent === "oferta") {
    if (/oferta|ciclos|formaci[oó]n profesional|grado medio|grado superior/.test(haystack)) boost += 0.15;
    if (/calendario|matr[ií]cul|admisi[oó]n/.test(haystack)) boost -= 0.05;
  } else if (intent === "calendario") {
    if (/calendario|pruebas extraordinarias|evaluaci[oó]n|junio|septiembre/.test(haystack)) boost += 0.15;
  }

  if (uniqueRequestedEtapas.length > 0 && chunk.etapa && uniqueRequestedEtapas.includes(chunk.etapa)) {
    boost += 0.10;
  }

  return boost;
}

function mentionsOtherStages(chunk, requestedEtapas) {
  if (requestedEtapas.length === 0) return false;

  const text = (chunk.source + " " + chunk.text).toLowerCase();
  const detected = [];

  if (/infantil|primaria/.test(text)) detected.push("primaria");
  if (/eso|educación secundaria obligatoria|educacion secundaria obligatoria/.test(text)) detected.push("eso");
  if (/bachillerato/.test(text)) detected.push("bachillerato");
  if (/formación profesional|formacion profesional|ciclos formativos|grado medio|grado superior/.test(text)) detected.push("fp");

  const uniqueDetected = [...new Set(detected)];

  return uniqueDetected.some(stage => !requestedEtapas.includes(stage));
}

const filtered = rawChunks
  .filter(chunk => isCompatibleWithIntent(chunk, intent))
  .filter(chunk => isCompatibleWithEtapa(chunk, uniqueRequestedEtapas))
  .filter(chunk => !mentionsOtherStages(chunk, uniqueRequestedEtapas));

const preferredByIntent = intent === "matricula"
  ? filtered.filter(chunk => chunk.tipo === "matricula")
  : filtered;

const baseSet = preferredByIntent.length > 0
  ? preferredByIntent
  : (filtered.length > 0 ? filtered : rawChunks.filter(chunk => isCompatibleWithEtapa(chunk, uniqueRequestedEtapas)));

const rescored = baseSet.map(chunk => ({
  ...chunk,
  adjustedScore: chunk.score + keywordBoost(chunk, intent)
}));

rescored.sort((a, b) => b.adjustedScore - a.adjustedScore);

const perSourceCount = {};
const selected = [];

for (const chunk of rescored) {
  const count = perSourceCount[chunk.source] || 0;

  if (count < 2 && selected.length < 4) {
    selected.push(chunk);
    perSourceCount[chunk.source] = count + 1;
  }
}

if (selected.length < 4) {
  for (const chunk of rescored) {
    const alreadyIncluded = selected.some(
      s => s.source === chunk.source && s.text === chunk.text
    );

    if (!alreadyIncluded) {
      selected.push(chunk);
    }

    if (selected.length >= 4) {
      break;
    }
  }
}

const finalChunks = selected.map((chunk, idx) => ({
  index: idx + 1,
  score: chunk.score,
  adjustedScore: chunk.adjustedScore,
  source: chunk.source,
  tipo: chunk.tipo,
  etapa: chunk.etapa,
  curso: chunk.curso,
  text: chunk.text.slice(0, 1800)
}));

const sourceSummary = [...new Set(finalChunks.map(c => c.source))].join(" | ");

const lowConfidence = finalChunks.length === 0 || (
  intent === "matricula" &&
  !finalChunks.some(c => c.tipo === "matricula")
);

const context = finalChunks
  .map(chunk =>
    `[${chunk.index}] Fuente: ${chunk.source}\nTipo: ${chunk.tipo || "desconocido"} | Etapa: ${chunk.etapa || "desconocida"} | Curso: ${chunk.curso || "desconocido"}\n${chunk.text}`
  )
  .join("\n\n---\n\n");

return [{
  json: {
    question: $('Set - Normalizar entrada').first().json.question,
    session_id: $('Set - Normalizar entrada').first().json.session_id,
    intent,
    lowConfidence,
    sourceSummary,
    requestedEtapas: uniqueRequestedEtapas,
    context,
    chunks: finalChunks,
    total_chunks: finalChunks.length
  }
}];

const question = $('Set - Normalizar entrada').first().json.question || '';
const session_id = $('Set - Normalizar entrada').first().json.session_id || '';
const agentOutput = $('AI Agent').first().json.output || '';
const chunks = $('Code - Construir contexto').first().json.chunks || [];

const sources = chunks.map(c => ({
  source: c.source,
  score: c.score
}));

return [{
  json: {
    question,
    answer: agentOutput,
    session_id,
    sources
  }
}];

const q = (($json.question || "") + "").toLowerCase();

let intent = "general";

if (q.includes("matrícul") || q.includes("matricula")) {
  intent = "matricula";
} else if (q.includes("admis")) {
  intent = "admision";
} else if (q.includes("ofert") || q.includes("ciclos")) {
  intent = "oferta";
} else if (q.includes("calendario") || q.includes("pruebas extraordinarias")) {
  intent = "calendario";
}

return [{
  json: {
    ...$json,
    intent
  }
}];

const intent = $json.intent || "general";
const question = ($json.question || "").toLowerCase();

const must = [];
const should = [];

if (intent === "matricula") {
  must.push({
    key: "tipo",
    match: { value: "matricula" }
  });
} else if (intent === "admision") {
  must.push({
    key: "tipo",
    match: { value: "admision" }
  });
} else if (intent === "oferta") {
  must.push({
    key: "tipo",
    match: { value: "oferta" }
  });
} else if (intent === "calendario") {
  must.push({
    key: "tipo",
    match: { value: "calendario" }
  });
}

if (question.includes("bachillerato")) {
  should.push({
    key: "etapa",
    match: { value: "bachillerato" }
  });
}

if (
  question.includes("formación profesional") ||
  question.includes("formacion profesional") ||
  question.includes(" fp") ||
  question.includes("ciclos formativos")
) {
  should.push({
    key: "etapa",
    match: { value: "fp" }
  });
}

let qdrantFilter = null;

if (must.length > 0 || should.length > 0) {
  qdrantFilter = {};
  if (must.length > 0) qdrantFilter.must = must;
  if (should.length > 0) qdrantFilter.should = should;
}

return [{
  json: {
    ...$json,
    qdrantFilter
  }
}];
